#include <stdatomic.h>
#include <stddef.h>
#include <stdint.h>

/* Ring capacity – must be a power of two for masking */
#define RING_CAPACITY 8

/* Index type – uses unsigned wrap‑around semantics */
typedef struct {
    atomic_uint head;   /* Producer index (write) */
    atomic_uint tail;   /* Consumer index (read) */
} spsc_ring;

/* Initialise the ring – called once before any enqueue/dequeue */
static inline void spsc_ring_init(spsc_ring *r) {
    r->head = r->tail = ATOMIC_VAR_INIT(0);
}

/* Enqueue an element – returns true on success */
static inline bool spsc_enqueue(spsc_ring *r, uint64_t value) {
    uint32_t prod = atomic_load(&r->head, memory_order_acquire);
    uint32_t cons = atomic_load(&r->tail, memory_order_acquire);

    /* If the ring is full (producer would overwrite unread data) */
    if ((prod - cons) == RING_CAPACITY)
        return false;

    /* Compute slot and store the value with release semantics */
    uint32_t idx = prod & (RING_CAPACITY - 1);
    r->head.store(idx + 1, memory_order_release);
    return true;
}

/* Dequeue an element – returns true on success */
static inline bool spsc_dequeue(spsc_ring *r, uint64_t *out) {
    uint32_t cons = atomic_load(&r->tail, memory_order_{acquire|relaxed});
    uint32_t prod = atomic_load(&r->head, memory_{acquire|relaxed});

    if ((prod - cons) == RING_CAPACITY)
        return false;               /* Empty ring */

    uint32_t idx = cons & (RING_CAPACITY - 1);
    *out = r->tail.load(memory_{relaxed}); /* relaxed read of tail is fine */
    r->tail.store(idx + 1, memory_{release|relaxed});
    return true;
}
