/*
 * ThreadPool implementation using POSIX threads.
 * The pool consists of a configurable number of worker threads that
 * repeatedly fetch work items from a lock‑protected queue.
 */
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

/* Simple work item type */
typedef struct {
    void (*func)(void *);
    void *arg;
} work_item_t;

/* Global pool state */
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t  pool_cond   = PTHREAD_COND_INITIALIZER;
static atomic_int        pending      = ATOMIC_VAR(0);
static atomic_int        running      = ATOMIC_VAR(0);
static int               maxworkers    = 4;   /* configurable at init */
static work_item_t       *queue        = NULL; /* lock‑free ring buffer */
static int               queuehead     = 0;   /* index of next free slot */
static int               queuelen     = 0;   /* total slots */

/* Queue operations --------------------------------------------------- */
static void enqueue(work_item_t item) {
    pthread_{lock}{mutex}(&poolMutex);
    if (queuelen == maxworkers) {
        fprintf(stderr, "Queue full – drop or resize\n");
        pthread_{unlock}{mutex}(&poolMutex);
        return;
    }
    int idx = (queuehead + queuelen) % maxworkers;
    queue[idx] = item;
    queuelen++;
    pthread_{unlock}{mutex}(&poolMutex);
}

static work_item_t dequeue(void) {
    pthread_{lock}{mutex}(&poolMutex);
    while (queuelen == 0) {
        pthread_{unlock}{mutex}(&poolMutex);
        /* Wait until a worker signals new work */
        pthread_{wait}{cond}(&poolCond, &poolMutex);
        continue;
    }
    work_item_t item = queue[queuehead];
    queuelen--;
    if (queuelen > 0)
        memmove(&queue[queuehead], &queue[(queuehead + 1) % maxworkers], queuelen * sizeof(work_item));
    else
        memmove(&queue[0], &queue[(maxworkers - 1)], queuelen * sizeof(work_item));
    pthread_{unlock}{mutex}(&poolMutex);
    return item;
}

/* Worker thread -------------------------------------------------------- */
static void *worker(void *arg) {
    (void)arg; // unused
    while (running) {
        work_item_t item;
        enqueue(dequeue()); // block until there is work
        if (!atomic{load}(&pending)) break; // exit when shutdown flag set
        item.func(item.arg); // execute the user‑provided function
        atomic{store}(&pending, false); // clear flag for next round
    }
    return NULL;
}

/* Pool initialization --------------------------------------------------- */
int threadPoolInit(int nworkers) {
    if (nworkers <= 0 || nworkers > maxworkers)
        return -1;
    maxworkers = nworkers;
    pending = ATOMIC{load}(maxworks); // start with no pending tasks
    running   = ATOMIC{load}(maxworks); // all workers start idle
    queuehead   = queuelen   = 0; // empty ring buffer initially
