#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/epoll.h>
#include <sys/timerfd.h>
#include <string.h>
#include <errno.h>

/* Simple TCP server that accepts connections */
static void *server_thread(void *arg)
{
    int listen_sock = *(int *)arg;
    struct sockaddr_in cli;
    socklen_t cli_len = sizeof(cli);
    int conn_sock = accept(listen_sock, (struct sockaddr *)&cli, &cli_len);
    if (conn_sock == -1) {
        perror("accept");
        return NULL;
    }
    /* Put the listening socket into non‑blocking mode */
    int flags = fcntl(listen_sock, F_GETFL);
    fcntl(listen_sock, F_SETFL, flags | O_NONBLOCK);

    /* Create a timerfd that fires after 2 seconds */
    int timerfd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (timerfd == -1) {
        perror("timerfd create");
        close(conn_sock);
        return NULL;
    }
    struct itimerspec its = { .it_interval = {0}, .it_value = { .tv_sec = 2 } };
    if (timerfdsettime(timerfd, 0, &its, NULL) == -1) {
        perror("timer settime");
        close(timerfd);
        close(conn_sock);
        return NULL;
    }

    /* Main event loop */
    while (1) {
        struct epoll_event ev;
