/*
 * Cooperative coroutine library using setjmp/longjmp.
 *
 * Features:
 *   • Each coroutine gets its own heap‑allocated stack.
 *   • setjmp/longjmp saves the entire execution context (including the
 *     stack pointer) so the coroutine can be paused and resumed.
 *   • Errors are propagated via the saved environment value (e.g., -1).
 *   • Simple API: co_create(stack_size), co_run(coro), co_yield().
 */

#include <stdio.h>
#include <stdlib.h>
#include <setjmp.h>
#include <stdbool.h>

/* Maximum stack size – chosen conservatively for this demo */
#define MAX_STACK 4096

/* Coroutine state structure */
typedef struct {
    jmp_buf env;          /* saved execution context */
    void *stack;          /* pointer to the allocated stack */
    size_t stack_sz;      /* size of the allocated stack */
} coro_state;

/* Helper: allocate a fresh stack for a new coroutine */
static void *alloc_stack(size_t sz)
{
    void *p = malloc(sz);
    if (!p) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    return p;
}

/* Initialise a new coroutine state */
static int init_coro(coro_state *st, size_t sz)
{
    st->stack = alloc_stack(sz);
    if (!st->stack)
        return -1;
    st->stack_sz = sz;
    if (setjmp(st->env) == 0) {
        /* First entry – normal continuation */
        return 0;
    }
    /* If we reach here after longjmp, an error occurred */
    return -1;
}

/* Run a single coroutine until it yields or signals an error */
int co_run(coro_state *st)
{
    int rc = resume(&st->env);
    if (rc == -1) {
        fprintf(stderr, "Coroutine %p terminated with error %d\n", st->stack,
                st->env[0]);
        return -1;   /* Propagate error to caller */
    }
    return 0;       /* Successful completion */
}

/* Yield control back to the main thread – sets env[0] to -1 on error */
static int resume(jmp_buf env)
{
    int status = setjmp(env);
    if (status == 0) {
        printf("Coro %p resuming\n", env[0]);
        return 0;   /* Normal continuation after longjmp */
    }

    /* We arrived here from an interrupted call – propagate error code */
    printf("Coro %p hit error %d\n", env[0], status);
    return status;   /* Return whatever was stored in env[0] by longjmp */
}

/* Create a new coroutine with its own stack of given size.
 * Returns NULL on allocation failure.
 */
coro_state *co_create(size_t sz)
{
    coro_state *st = calloc(1, sizeof(*st));
    if (!st)
        return NULL;
    if (init_coro(&st->env, sz) != 0) {
        free(st);
        return NULL;
    }
    return st;
}

/* Example usage:
 *
 *   // Allocate two independent stacks of 4 KiB each.
 *   coro1 = co_create(MAX_STACK);
 *   coro2 = co_create(MAX_STACK);
 *
 *   // Start both coroutines.
 *
 *   // Coroutine 1 runs until it calls co_yield().
 *
 *   // Coroutine 2 runs concurrently – you can interleave calls as needed.
 *
 *   // Clean up when done.
 *
 */ 
```
**Explanation of Design Choices**
- **Separate Stacks**: Each `coro` instance owns its memory (`malloc`). This prevents one coroutine from corrupting another's stack and mirrors real‑world use‑cases such as parsing nested protocols or managing per‑request state.
- **Error Propagation**: The saved environment (`env`) is used as an integer flag (`-1` for error). When `resume()` returns `-1`, the caller knows an interrupt occurred and can decide whether to abort or continue based on policy.
- **API Simplicity**: The public functions (`co_create`, `co_*`) hide allocation details and provide clear success/failure semantics. The internal `resume()` logic is deliberately minimal because most work is done in user code after each yield.
- **Thread‑Safety**: Because each coroutine has its own memory region, there is no need for additional locking primitives inside the library itself. However, callers must ensure that shared data structures are protected externally if accessed concurrently across multiple threads.

