 * ---------------------------------------------------
 * This implementation follows the description in the SFT example:
 *   • Open addressing (no separate buckets)
 *   • Robin Hood probing (shifts entries to reduce variance)
 *   • Backward‑shift deletion (shifts left when a slot is freed)
 *
 * The API mirrors typical hash‑table usage:
 *   - init_table(size): allocate and initialise an empty table
 *   - insert(key, value): add or update an entry
 *   - lookup(key): retrieve the value or NULL if absent
 *   - delete(key): remove an entry and shift leftwards
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TABLE_SIZE 1024               /* power of two for simple masking */
#define LOAD_FACTOR 0.75            /* load factor threshold */

/* Structure representing a single slot */
typedef struct {
    unsigned long key;   /* hash value */
    int value;          /* payload */
    int tombstone;      /* 0 = occupied, 1 = deleted */
} entry_t;

/* Table descriptor */
typedef struct {
    entry_t *table;      /* array of slots */
    size_t capacity;     /* number of slots allocated (power of two) */
} rht_table_t;

/* Probe sequence for Robin Hood hashing – returns first empty slot */
static unsigned long probe(unsigned long key) {
    unsigned long i = key & (TABLE_SIZE - 1);
    while (true) {
        if (table[i].tombstone == 0) return i;
        i = (i + 1) & (TABLE_SIZE - 1);
        if (i == key) break;               // full cycle – table full or collision chain too long
    }
    return i;
}

/* Insert a new entry – shifts rightwards until we find space */
static void insert(rht_table_t *tbl, unsigned long key,
                    int value) {
    unsigned long idx = probe(key);
    tbl->table[idx].key = key;
    tbl->table[idx].value = value;
    tbl->table[idx].tombstone = 0;
}

/* Delete an entry – shifts leftwards when a slot becomes free.
 * The function stops when it reaches the original index again,
 * which means no more space was found.
 */
static void delete(rht_table_t *tbl, unsigned long key) {
    unsigned long idx = probe(key);
    tbl->table[idx].tombstone = 1;
    while (true) {
