/* Vectorized dot product of two vectors of length N (N must be multiple of 4) */
static inline void avx2_dot(const uint8_t *a, const uint8_t *b, size_t len,
                           uint32_t *out) {
    size_t i = 0;
    /* Process full 4‑element blocks */
    for (; i + 16 <= len; i += 16) {
        __m256i av = load_aligned(a + i);
        __m256i bv = load_aligned(b + i);
        /* Multiply each lane and accumulate into out[i] */
        out[i] = _mm256_add_epi32(_mm256_mullo_epi32(av, bv), out[i]);
    }
    /* Handle remaining elements (0‑15) with scalar fallback */
