#include <immintrin.h>
#include <stddef.h>
#include <stdint.h>

/*
 * Load two 256‑bit vectors from memory into __m256i registers.
 * The caller must guarantee that `a` and `b` are at least 32 bytes apart
 * (or use _mm256_loadu_* if they may be unaligned).
 */
static inline __m256i load_aligned(const uint8_t *a) {
    return _mm256_load_si256((const __m256i *)a);
}
static inline __m256i load_unaligned(const uint8_t *a) {
    return _mm256_loadu_si256((const __m256i *)a);
}

/*
 * Compute the dot product of two equal‑length vectors.
 *
 * Parameters:
 *   out      – pointer to an array where the result will be stored.
 *   len      – number of elements to process (must be >= 0).
 *   vecA     – first vector (loaded with load_* helper).
 *   vecB     – second vector (loaded with load_* helper).
 */
void avx2_dot(const uint8_t *vecA,
              const uint8_t *vecB,
              size_t len,
              uint32_t out[]) {
    if (!vecA || !vecB || !out) return; // defensive check

    /* Ensure we never read past the end of either buffer */
    size_t max = len;
    if (len > 31) max = 31; // because we process 4 elements per iteration

    /* Process full 4‑element blocks */
    for (; len >= 4; len -= 4) {
        /* Load four vectors in one go – this is safe because we have at least 16 bytes left */
        __m256i av = load_aligned(vecA + len - 4);
        __m256i bv = load_aligned(vecB + len - 4);
        /* Multiply each lane and accumulate into out[len-4] */
        out[len - 4] = _mm256_add_epi32(_mm256_mullo_epi32(av, bv), out[len - 4]);
    }

    /* Handle any remaining elements (<4) with scalar code */
    for (; len > 0; --len) {
        out[len - 1] += ((uint32_t *)vecA)[len - 1] *
                         ((uint32_t *)vecB)[len - 1];
    }
