{
    uint64_t val = 0xA5A5A5A5A5A5A5A5ULL;
    printf("Original : %llu\n", (unsigned long long)val);
    printf("Reversed : %llu\n", (unsigned long long)reverse_bits_parallel(val));
    return 0;
}
