    sa.sa_sigaction = segv_handler;   // SA_SIGINFO variant
    sa.sa_flags = SA_SIGINFO | SA_RESTART; // restart syscalls automatically
    if (sigaction(SIGSEGV, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

