#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <setjmp.h>
#include <string.h>
#include <unistd.h>

/* Global jmp buffer – shared between threads */
static jmp_buf env;
static volatile int recovered = 0;

/* Signal handler – prints faulting address and jumps back */
static void segv_handler(int signo, siginfo_t *info, void *ucontext)
{
    (void)signo; (void)ucontext; /* unused */
    printf("[%d] %s               %s\n", signo,
           strsignal(signo), info->si_addr);
    if (!recovered) {
        /* Recover from the signal */
        printf("[%d] SIGSEGV               %s\n", signo,
               strsignal(signo));
        siglongjmp(env, 1);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_flags = SA_SIGINFO | SA_RESTART; /* restart syscalls */
    sa.sa_sigaction = segv_handler;          /* use sa_sigaction */
    if (sigaction(SIGSEGV, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Install longjmp buffer – must be in shared memory for other threads */
    if (setjmp(env) == 0) {
        puts("Running normally…");
        return EXIT_SUCCESS;
    }

    /* Attempt to trigger SIGSEGV in another thread */
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return EXIT_FAILURE;
    }
    if (pid == 0) { /* child */
        char *ptr = malloc(0);          /* UB -> triggers SEGV */
        if (!ptr)
            _exit(EXIT_FAILURE);
        *(char *)ptr = 'A';              /* write through NULL -> SEGV */
        free(ptr);
        _exit(EXIT_SUCCESS);
    } else { /* parent */
        int status;
        waitpid(pid, &status, 0);
        printf("[parent] child terminated with status %d\n", status);
    }

    printf("[parent] recovered from signal\n");
    return EXIT_SUCCESS;
}
```
### How it works
1. **Handler registration** – We fill a `struct sigaction` with:
   - `sa.sa_flags = SA_SIGINFO | SA_RESTART` so that signals are delivered as POSIX signals and system calls are automatically restarted.
   - `sa.sa._sa._sa._sa._sa._sa._sa._si` points to our custom handler (`segv`) which receives three arguments (`signo`, `info`, `ucontext`).
2. **Longjmp buffer** – A global `jmpbuf env` is used so that any thread can jump back to the point after the call to `setjmp`.
3. **Triggering the fault** – Inside a child process we allocate zero bytes (`malloc(0)`). On many platforms this returns either NULL or a unique pointer; dereferencing it yields an invalid address → segmentation fault.
4. **Recovery path** – When the fault occurs inside the child:
   - The kernel invokes our handler with `si->si__addr` containing the faulting address.
   - The handler prints diagnostic information.
   - Because we never called `longjmp`, execution continues after the call to `setjmp`.
5. **Parent continuation** – After forking we wait for the child to finish (`waitpid`). Once it exits we print *"recovered from signal"* confirming that no crash occurred.
6. **Safety notes**
   - Using only POSIX APIs (`setjmp`/`longjmp`) avoids undefined behaviour that older BSD‑style handlers could introduce.
   - The handler must not call any non‑async‑signal‑safe functions; printing is safe because it uses only standard library calls.
   - If you need more complex recovery logic you can store additional state in shared memory before calling `longjmp`.

### Why this pattern is preferred over older BSD handlers?
- **No global variables**: Older BSD handlers often relied on globals like `_sysmsg`; those are unsafe in multithreaded programs.
- **Signal mask handling**: Modern handlers can manipulate their own mask safely; older ones required careful ordering.
- **Portability**: POSIX guarantees that only one instance of each signal type runs at a time; using only async‑signal‑safe functions ensures correctness across all UNIX variants.

