 * Concurrent Trie (prefix tree) using RCU for lock‑free reads.
 * The design follows the classic "RCU‑protected read‑mostly" pattern:
 *   • Readers traverse the trie inside rcu_read_lock()/rcu_read_unlock().
 *   • Writers replace nodes with rcu_assign_pointer() and defer freeing
 *     with call_rcu().
 *   • Memory ordering is provided by the RCU read‑side critical section.
 */

#include <linux/rcupdate.h>
#include <linux/slab.h>
#include <linux/string.h>
#include <stddef.h>

/* Trie node definition */
struct rcu_node {
    struct rcu_head rcu;          /* Deferred free */
    u8 prefix[32];               /* IPv4 prefix (max 32 bits) */
    u8 depth;                    /* Number of bits in this node */
    struct rcu_node **children[256];
};

/* Root of the trie – allocated once */
static struct rcu_root trie_root;

/* Helper to allocate a new node */
static struct rcu_node *__alloc(gfp_t flags)
{
    return kmalloc(sizeof(*__alloc), flags);
}

/* Insert a prefix into the trie – returns pointer to leaf or NULL on error */
static struct rcu_node *__insert(struct rcu_node **root,
                                 const u8 prefix[], size_t len)
{
    struct rcu_node **child = root->children;
    if (!*child)
        child = __alloc(GFP_KERNEL);
    if (!*child)
        return NULL;
    return __insert(child, prefix, len);
}

/* Lookup – returns pointer to leaf or NULL */
static struct rcu_node *__lookup(const u8 prefix[], size_t len,
                                 u8 key)
{
    struct rcu_node **child = root->children;
    while (*child) {
        if (memcmp(prefix, child->prefix, MIN(len, sizeof(child->prefix))))
            child = &(*child)->children[key & 0xFF];
        else if (key == len)
            return child; /* exact match */
        else if (key < len)
            child = &(*child)->children[0]; /* go left */
        else /* key > len */
            child = &(*child)->children[1]; /* go right */
    }
    return NULL;
}

