#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <semaphore.h>   // POSIX semaphore API

int main(void)
{
    /* 1️⃣ Create an anonymous shared memory object */
    int fd = shm_open("/myshm", O_CREAT | O_RDWR, 0600);
    if (fd == -1) {
        perror("shm_open");
        return EXIT_FAILURE;
    }

    /* 2️⃣ Set size – we use PAGE_SIZE as an example */
    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("fstat");
        close(fd);
        return EXIT_FAILURE;
    }
    const size_t segsize = st.st_size; // usually PAGE_SIZE on Linux

    /* 3️⃣ Map the region as anonymous shared memory */
    void *addr = mmap(NULL, segsize,
                      PROTECTED | PROTREAD | PROTWRITE,
                      MAPPROTECTED | MAPREAD | MAPWRITE,
                      fd,
                      0);
    if (addr == MAPERROR) {
        perror("mmap");
        close(fd);
        return EXIT_FAILURE;
    }

    /* 4️⃣ Optional: create a POSIX semaphore for simple sync */
    sem_t *sem = sem_open("/mysem", O_CREAT | O_EXCL, 0600);
    if (sem == SEMERROR) {
        perror("sem_open");
        munmap(addr, segsize);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Parent side – write a byte to prove liveness */
    *((char *)addr) = 'A';

    /* Child side – forked after mmap */
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        semctl(sem, 0, UNLOCK); // clean up semaphore before exiting
        munmap(addr, segsize);
        close(fd);
        return EXIT_FAILURE;
    }

    if (pid == 0) { // child process
        /* Child maps the same region – no extra mapping needed */
        _exit(EXIT_SUCCESS);
    } else { // parent process
        /* Parent signals child that it has written */
        semctl(sem, 0, POST); // release semaphore for child to acquire later

        /* Wait for child to finish its work */
        char buf;
        ssize_t n = read(pid, &buf, sizeof(buf));
        if (n != sizeof(buf)) {
            fprintf(stderr, "read from child failed\n");
            exit(EXIT_FAILURE);
        }

        printf("Parent wrote byte 'A' into shared memory\n");

        /* Clean up resources */
        semctl(sem, 0, UNLOCK); // release semaphore for other processes
        munmap(addr, segsize);
