        // Load previous value atomically (acquire) to see if it changed.
        let prev_val = self.top.load(Ordering::Acquire);
        if prev_val == elem as *mut u8 as *mut u8 {
            // Duplicate detected – treat as failure to avoid ABA.
            return false;
