/// * `MyRc<T>` owns a raw pointer (`NonNull<T>`) to the value.
/// * It implements `Deref` so callers can treat it like a normal reference.
/// * It implements `Drop` to decrement the counter and free the value when it reaches zero.
pub struct MyRc<T> {
    ptr: NonNull<T>,
}

impl<T> MyRc<T> {
    /// Construct a new `MyRc` from a raw pointer. The caller must guarantee
    /// that the pointer is non‑null and points to a valid allocation of type T.
    pub unsafe fn new(ptr: NonNull<T>) -> Self {
        // SAFETY: we have just created a non‑null pointer; no other thread can
        // access it yet because we are constructing the object in an exclusive
        // context (e.g., inside a function or after taking exclusive ownership).
        Self { ptr }
    }
}

impl<T> Deref for MyRc<T> {
    type Target = T;
    fn deref(&self) -> &Self::Target {
        // SAFETY: we know `self.ptr` is non‑null because we constructed it with
        // `NonNull::new`.
        unsafe { &*self.ptr }
    }
}

impl<T> Drop for MyRc<T> {
    fn drop(&mut self) {
        // Decrement the reference count; if it reaches zero we free the memory.
