pub struct MpscChannel {
    /// Queue of items awaiting consumption.
    queue: VecDeque<u32>,
    /// Mutex protecting `queue`.
    inner_lock: Mutex<VecDeque<u32>>,
    /// Condition variable used to wake up blocked senders when space becomes available.
    condvar: Condvar,
}

impl MpscChannel {
    /// Creates an empty MPSC channel.
    pub fn new() -> Self {
        Self {
            queue: VecDeque::new(),
            inner_lock: Mutex::new(VecDeque::new()),
            condvar: Condvar::new(),
        }
    }

    /// Sends a value to the consumer. Blocks if the buffer is full.
    pub fn send(&self, item: u32) -> Result<(), SendError> {
        // Fast path – try to push without blocking.
        if self.queue.len() < self.inner_lock.lock().unwrap().len() {
            self.queue.push_back(item);
            return Ok(());
        }

        // Need to wait until there is room in the queue.
        let mut cv = self.condvar;
        let mut lock = self.inner_lock;

        // Spawn a helper thread that will drain items from `queue` into `rx`
        // when it becomes non‑empty. This avoids blocking the caller while still
        // guaranteeing that only one sender runs at a time (the mutex).
        let sender_thread = std::thread::spawn(|| {
            while lock.lock().unwrap().is_some() {
                // Wait until there is at least one item in `queue`.
                while !self.queue.is_empty() { cv.wait(&mut lock); }
                // Drain all available items from `queue` into `rx`.
