use std::iter::{self, Iterator};
use std::slice;

/// A custom iterator that yields a *reference* sliding window over `data`.
/// It returns `&[T]` where each element points into the original slice,
/// allowing zero‑allocation access to any window.
pub struct SlidingWindow<'a, T> {
    data: &'a [T],
    // Number of elements we want in each window.
    win_len: usize,
}

impl<'a, T> SlidingWindow<'a, T> {
    /// Create an iterator that yields windows of length `win_len`.
    /// The iterator is *lazy*: it never materialises more than one window at a time.
    pub fn new(data: &'a [T], win_len: usize) -> Self {
        Self { data, win_len }
    }
}

impl<'a, T> Iterator for SlidingWindow<'a, T> {
    type Item = &'a [T];

    fn next(&mut self) -> Option<Self::Item> {
        // If we have fewer elements than the requested window size,
        // we cannot produce a full window yet.
        if self.data.len() < self.win_len {
            return None;
        }

        // Compute the start index of the next window.
        let start = self.data.len() - self.win_len;
        let end = start + self.win_len;

        // SAFETY: We have already checked that `start + win_len <= data.len()`,
        // so all indices are within bounds.
        let slice = unsafe { &self.data[start..end] };
        Some(slice)
    }
}
```
### Why this avoids allocation
1. **No intermediate collection** – The iterator holds only two fields (`data` reference and `win_len`). When `next()` is called, it computes the slice bounds on‑the‑fly using pointer arithmetic; no heap allocation occurs.
2. **Zero‑copy semantics** – Each returned reference points directly into the original buffer; no copying or cloning happens.
3. **Lazy evaluation** – The iterator does not pre‑compute all windows; it produces one at a time as requested by the caller (e.g., via `.map(|w| w[0])`).
4. **Borrow safety** – The iterator borrows from `self`, which itself borrows from `data`. Because we only read immutable slices (`&[T]`) and never move out of them, Rust’s borrow checker guarantees safety as long as callers respect the lifetime of each returned reference.
### Example usage
```rust
fn main() {
    let data = [10u8, 20u8, 30u8, 40u8];
    let mut iter = SlidingWindow::new(&data[..], 2);
    for win in iter {
        println!("{:?}", win); // prints &[10u8; 2], &[20u8; 2]
    }
}
```
### Edge‑case handling
- **Empty input**: If `data` is empty and any non‑zero `win_len` is requested, `next()` immediately returns `None`.
- **Window larger than input**: When `self.data.len() < win_len`, iteration yields nothing until enough elements accumulate (e.g., after processing more data).
- **Lifetime**: The returned references are tied to the lifetime of `iter`; they become invalid once iteration ends or when a new reference is taken from another source.
