/// The cache holds an LRU doubly‑linked list (`head`/`tail`) and a hash map for O(1) look‑ups.
#[derive(Debug)]
struct LruCache<K, V> {
    map: Arc<RwLock<HashMap<K, Rc<Node>>>>,
    head: *mut Node,
    tail: *mut Node,
}

