    /// Create a new cache with an initial capacity (default 64).
    pub fn new(capacity: usize) -> Self {
        let mut map = HashMap::with_capacity(capacity);
        // Initialise the doubly‑linked list with dummy head/tail nodes.
        let mut head = Box::new(Node { key: K::default(), value: V::default(), prev: ptr::null_mut(), next: ptr::null_mut() });
        let mut tail = Box::new(Node { key: K::default(), value: V::default(), prev: ptr::null_mut(), next: ptr::null_mut() });
        // Insert dummy nodes so that `head`/`tail` are always valid.
        unsafe { (*head.as_ptr()).prev = ptr::null_mut(); (*head.as_ptr()).next = ptr::null_mut(); }
        unsafe { (*tail.as_ptr()).prev = ptr::null_mut(); (*tail.as_ptr()).next = ptr::null_mut() };
        Self { map: Arc::<RwLock<HashMap<K, Rc<Node>>>>{ inner: Arc::<RwLock>::new(map) }, head, tail }
    }

    /// Acquire a read lock for concurrent reads.
    pub fn get(&self, key: &K) -> Option<&V> {
        let mut guard = self.map.read().unwrap();
        let entry = guard.get(key).copied();
        if entry.is_some() {
            // Move accessed node to the front of the LRU list.
            let node = entry.unwrap();
            // Update pointers under write lock (only needed if we ever modify them).
            unsafe { (*node.prev).next = node; (*node.next).prev = node; }
            Some(&node.value)
        } else {
            None
        }
    }

    /// Acquire a write lock for updates (insert or evict).
    pub fn set(&self, key: &K, value: &V) -> Option<&V> {
