                unsafe { (*self.tail).prev = ptr::null(); (*self.tail).next = ptr::null(); }
                unsafe { (*self.head).prev = ptr::null(); (*self.head).next = ptr::null(); }
                Some(&(*tail).value)
            } else {
                None
            }
        }
    }
