/// Derive macro that computes the size and alignment of a struct at compile time.
/// Usage: #[derive(StructSize)]
pub fn struct_size(input: TokenStream) -> TokenStream {
    // 1️⃣ Parse the input token stream into a Syn parse tree.
    let input = parse::ParseBuffer::new(input);
    let input = input.parse().expect("failed to parse input");

    // 2️⃣ Implement the derive trait for our custom macro.
    impl syn::Derive for StructSize {
        fn derive(ctx: syn::DeriveContext) {
            // 3️⃣ Retrieve the concrete type we are deriving.
            let ty = ctx.ty();
            // 4️⃣ Compute size at compile time using std::mem.
            let size = mem::size_of::<ty>();
            // 5️⃣ Compute alignment using align_of.
            let align = align_of::<ty>();

            // 6️⃣ Emit a const item named "SIZE" with the computed values.
            let mut stream = TokenStream::new();
            stream.extend(quote! {
                pub const SIZE: usize = #size;
                pub const ALIGN: usize = #align;
            });

            // 7️⃣ Attach the generated constants to the current module's namespace.
            ctx.extend(stream);
        }
    }
}
