use std::arch::x86_64;
use std::ptr;

/// Computes the sum of an array of 32‑bit floats using AVX2 intrinsics.
///
/// # Safety
/// * The input pointer must be **16‑byte aligned** because we use `_mm256_loadu_si256`.
/// * The length must be a multiple of 8 (the size of an AVX2 register).
pub fn sum_floats(data: *const u8, len: usize) -> i32 {
    // Ensure the pointer is properly aligned for AVX2 loads.
    let ptr = data.cast::<__m128>();
    if ptr.as_ptr() as usize % align_of(__m128) != 0 {
        panic!("Pointer not 16‑byte aligned for AVX2 load");
    }

    // Convert the byte pointer to a slice of __m128 elements.
    let slice = unsafe { std::slice::from_raw_parts(ptr, len / align_of(__m128)) };

    // Load the data into an __m128 vector (unaligned load works for any alignment).
    let vec = unsafe { _mm256_loadu_si256(slice.as_ptr()) };

    // Use horizontal add to sum all lanes in parallel.
    // _mm256_hadd_* performs pairwise addition across lanes; we then add the two results together.
    let sum = unsafe { _mm256_hadds_epi32(vec, vec) };

    // Convert each lane back to i32 by truncating toward zero (the intrinsic already does this).
    let total = unsafe { sum.as<i32>() };

    total as i32
}
```
