    inner: Box<dyn Error + Send + Sync>,
    msg: String,
}

impl WrappedError {
    fn new(inner: Box<dyn Error + Send + Sync>, msg: &str) -> Self {
        Self { inner, msg }
    }
}

impl fmt::Display for WrappedError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Show the inner error first (if it implements Display)
        if let Some(inner_msg) = self.inner.as_ref().map(|e| e.to_string()) {
            write!(f, "{}", inner_msg)
        } else {
            write!(f, "{}", self.msg)
        }
    }
}

impl Error for WrappedError {}

// Implement From for each concrete error type we want to wrap.
impl From<std::io::Error> for WrappedError {
    fn from(err: std::io::Error) -> Self {
        // Preserve the original io error as the inner component.
        Self { inner: Box::new(err), msg: "I/O error".into() }
    }
}

