    let addr_err = std::net::AddrParseError;

    let io_wrapped = WrappedError::<std::io::ErrorKind>::from(io_err);
    let addr_wrapped = WrappedError::<std::net::AddrParseError>::from(addr_err);

    // Propagate both errors using ? operator – each layer will display its own message.
    Err(() => io_wrapped).context("network operation")?; // returns Err(() => Err(() => ...))
}
