use std::sync::{Arc, Mutex};
use crossbeam::channel::{self as cb_channel};
use std::thread;

/// A simple worker that receives tasks from the channel.
struct Worker {
    /// Shared state for graceful shutdown.
    quit: Arc<Mutex<bool>>,
}

impl Worker {
    fn new(quit: Arc<Mutex<bool>>) -> Self {
        Self { quit }
    }
}

impl Worker {
    fn run(&self) {
        // In real code this would loop forever or until quit is set.
        // Here we just sleep to avoid busy‑waiting.
        thread::sleep(std::time::Duration::from_millis(100));
    }
}

/// The public API of the ThreadPool.
pub struct ThreadPool {
    /// Channel used to distribute tasks between workers.
    queue: cb_channel::<()>,
    /// Number of worker threads (can be tuned).
    workers: usize,
    /// Shared quit flag for graceful shutdown.
    quit: Arc<Mutex<bool>>,
}

impl ThreadPool {
    pub fn new(workers: usize) -> Self {
        let queue = cb_channel::<()>();
        let quit = Arc::new(Mutex::new(false));
        let mut workers = Vec::with_capacity(workers);
        for _ in 0..workers {
            workers.push(Worker { quit });
        }
        // Spawn one worker per OS thread (or any number you choose).
        for w in &mut workers {
            let handle = thread::spawn(|| w.run());
            // Store handles so we can join them later if needed.
            // For simplicity we keep them alive until shutdown.
            handle;
        }
        Self { queue, workers: workers.len(), quit }
    }

    /// Submit a closure to be executed by any worker.
