       Some(_ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _ as _) =>
           stats_collector().await,
       None =>
           ()
   }
