// TestConvertBytesToImmutableString verifies that ConvertBytesToImmutableString
// returns an immutable string whose underlying data points directly to the input
// byte slice and does not allocate additional heap memory.
func TestConvertBytesToImmutableString(t *testing.T) {
    tests := []struct {
        name     string
        input    []byte
        wantErr  bool // we expect no error for valid UTF‑8 input
        wantSize int   // size of the returned string (should equal len(input))
    }{
        {"empty slice", []byte{}, false, 0},
        {"single byte", []byte{'a'}, false, 1},
        {"multi‑byte UTF‑8", []byte{0x41, 0x42, 0x43}, false, 3},
        {"non‑UTF‑8", []byte{0xFF}, true, -1}, // utf8.ValidRune will reject this case
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            gotStr, err := ConvertBytesToImmutableString(tt.input)
            if (err != nil) != tt.wantErr {
                t.Fatalf("unexpected error state: got %v want %v", err != nil, tt.wantErr)
            }
            if err == nil && tt.wantErr {
                t.Fatalf("expected error but got none")
            }
            if len(gotStr) != tt.wantSize {
                t.Fatalf("expected length %d, got %d", tt.wantSize, len(gotStr))
            }
            // Verify that the underlying data is exactly the same as the input.
            // We can do this by comparing pointer equality after converting back to a slice.
            // First obtain a slice of the original bytes.
            origPtr := unsafe.Pointer(&tt.input[0])
            origLen := uintptr(len(tt.input))
            origSlice := (*[1 << 30]byte)(unsafe.SliceData(origPtr))[:origLen]
            if !reflect.DeepEqual(*origSlice[:], tt.input) {
                t.Fatalf("underlying data mismatch: got %v want %v", *origSlice[:], tt.input)
            }
            // Ensure the returned string is immutable – attempting to modify should panic.
            defer func() {
                if r := recover(); r == nil {
                    t.Fatalf("expected panic when mutating returned immutable string")
                }
            }()
            _ = (*string)(unsafe.Pointer(&gotStr))[0] = 'X' // illegal write attempt
        })
    }
}
