// Config holds parameters for the pipeline.
type Config struct {
    // Max number of items each worker can hold before blocking.
    BufferSize int
}

// Stage represents a single processing function applied to an item.
type Stage func(ctx context.Context, in <-chan Item) <-chan Item

// NewPipeline creates a pipeline with configurable buffer sizes per stage.
func NewPipeline(cfg Config) (*Pipeline, error) {
    if cfg.BufferSize <= 0 {
        return nil, errors.New("bufferSize must be > 0")
    }
    p := &Pipeline{stages: make([]Stage, 0), ctx: context.Background()}
    return p, nil
}

// Pipeline holds the list of stages and the shared context.
type Pipeline struct {
    stages []Stage
    ctx     context.Context // shared cancellation context for all stages
}

// Run launches the pipeline with a start item that will be sent downstream.
func (p *Pipeline) Run(startItem Item) error {
    // Start the first stage in its own goroutine so we can wait for it to finish.
    go func() {
        err := p.runStage(startItem)
        if err != nil {
            fmt.Fprintf(os.Stderr, "stage error: %v\n", err)
        }
        // Signal completion to the main goroutine.
        close(p.ctx.Done())
    }()
    return nil
}

// runStage executes one stage until it returns an error or receives a stop signal.
