/* Helper: evaluate one pixel in the complex plane */
static PyObject *pixel(double real, double imag) {
    double zr = 0.0, zi = 0.0;
    int maxit = 1000; // enough for typical images
    for (int i = 0; i < maxit; ++i) {
        double tmp = zr * zr - zi * zi + real;
        zi = 2 * zr * zi + imag;
        zr = tmp;
        if (zr * zr + zi * zi > 4) break; // escape condition
    }
    if (i == maxit) return PyLong_FromLong(1); // inside set → black pixel
    else return PyLong_FromLong(0); // outside → white pixel
}

