static PyObject *render(PyObject *self, PyObject *args) {
    /* Parse arguments: width height maxit */
    int w = PyInt_AsLong(PyTuple_GetItem(args, 0));
    int h = PyInt_AsLong(PyTuple_GetItem(args, 1));
    int maxit = PyInt_AsLong(PyTuple_GetItem(args, 2));

    /* Allocate NumPy array of shape (w*h) */
    npy_intp dims[2] = {w*h};
    PyObject *arr = PyArray_SimpleNewFromDims(2, dims,
                                            NPY_DOUBLE,
                                            NULL);
    double *data = (double *)PyArray_DATA((PyArrayObject *)arr);

    /* Compute all pixels in a tight loop – no Python calls here */
    for (int y = 0; y < h; ++y) {
        for (int x = 0; x < w; ++x) {
            data[y*w + x] = pixel((x - w/2)*(maxit-1)/w,
                                 (y - h/2)*(maxit-1)/h);
