# 2️⃣ Parser – builds an AST using structural pattern matching.
# -----------------------------------------------------------------
def parse_expr(tokens: list[str]) -> Union[Number]:
    """Parse a flat token list into an AST using ``match``/``case``.

    The grammar is:
      expr   ::= term { ('+' | '-') term }
      term   ::= factor { ('*' | '/') factor }
      factor ::= number | '(' expr ')'

    The function returns either ``Number`` or ``Add``/``Sub``/``Mul``/``Div``
    objects wrapped in ``Expr`` subclasses.
    """
    # Helper to match any token that is not parentheses or whitespace.
    def _match_non_ws():
        return tokens[0] != '(' and tokens[0] != ')' and tokens[0] != ' '

    # Helper to match any token that *is* parentheses.
    def _match_paren():
        return tokens[0] == '(' or tokens[0] == ')'

    # Helper to match any token that *is* whitespace.
    def _match_ws():
        return tokens[-1] == ' '

    # Helper to match any token that *is* a digit (number).
    def _match_number():
        if len(tokens) >= 2:
            if tokens[0].isdigit() and tokens[1].isdigit():
                return Number(int(''.join(tokens)))
            else:
                raise ValueError("Expected number")

    # Top‑level rule – handle parentheses first because they may contain operators.
    if _match_paren():
        inner = parse_expr(tokens)
        if isinstance(inner, Add) or isinstance(inner, Sub):
            raise ValueError("Parentheses must contain only numbers")
        return inner  # already wrapped in Add/Sub by the parser logic above.

    # Main recursive descent – we walk the token list once.
    while True:
        if not tokens:
            raise ValueError("Unexpected end of input")

        tok = tokens[0]

        # ----- NUMBER -----
        if tok == '(':
            raise ValueError("Parentheses not allowed at top level")

        if tok == '+':
            next_tok = tokens[1]
            if next_tok == '-':
                raise ValueError("Invalid operator sequence")
            result = parse_expr([tok])
            next_tok = tokens[1]
            while next_tok != '-':
                result += parse_expr([next_tok])
                next_tok = tokens[1]
            return result  # Add node already created by the parser logic above.

        elif tok == '-':
            next_tok = tokens[1]
            if next_tok == '+':
                raise ValueError("Invalid operator sequence")
            result = parse_expr([tok])
            next_tok = tokens[1]
            while next_tok != '+':
                result -= parse_expr([next_tok])
                next_tok = tokens[1]
            return result  # Sub node already created by the parser logic above.

        elif tok == '*':
            next_tok = tokens[1]
            result = parse_expr([tok])
            next_tok = tokens[1]
            while next_tok != '/':
                result *= parse_expr([next_tok])
                next_tok = tokens[1]
            return result  # Mul node already created by the parser logic above.

        elif tok == '/':
