class ConsistentHashRing:
    """A simple consistent hashing ring for node placement.
    Nodes are identified by their IP address (or any hashable key).
    """

    def __init__(self, num_buckets: int = 1024):
        self.num_buckets = num_buckets
        # Store nodes in a dict keyed by their hash value.
        self._nodes: dict[int, list[Tuple[str, int]]] = defaultdict(list)
        # Initialise each bucket with the first `num_buckets` nodes.
        for i in range(self.num_buckets):
            self._nodes[i].append(("node", i))

    def _hash(self, key: str) -> int:
        """Return an integer hash of `key`. We use SHA‑256 truncated to 32 bits.
        This provides good distribution while keeping the implementation simple.
        """
        return int(hashlib.sha256(key.encode()).hexdigest()[:8], 16)

    def add_node(self, node: str) -> None:
        """Insert `node` into the ring at its hash bucket."""
        if not node:
            raise ValueError("Node name cannot be empty")
        h = self._hash(node)
        # Insert into existing buckets; keep order deterministic for reproducibility.
        for bucket in list(self._nodes.keys()):
            if h % len(bucket) == 0:
                self._nodes[bucket].append((node, h))
                break
            elif h < len(bucket):
                self._nodes[bucket].insert(
                    0,
                    (node, h),
                )
            else:
                # Wrap around to the next bucket when we exceed current size.
                next_bucket = (h // len(bucket)) + 1
                if next_bucket >= len(self._nodes):
                    next_bucket = 0
                self._nodes[next_bucket].append((node, h))
                break

    def remove_node(self, node: str) -> None:
        """Remove `node` from its current bucket; if absent raise ValueError."""
        if not node:
            raise ValueError("Node name cannot be empty")
        h = self._hash(node)
        for bucket in list(self._nodes.keys()):
            if node in self._nodes[bucket]:
                del self._nodes[bucket][self._nodes[bucket].index((node, h))]
                break
            elif h < len(bucket):
                idx = bucket.index((node, h))
                del bucket[idx]
                break
            else:
                next_idx = (h // len(bucket)) + 1
                if next_idx >= len(self._nodes):
                    next_idx = 0
                del bucket[:next_idx]
                break

    def get_owner(self) -> Tuple[str, int]:
        """Return a tuple ``('node', index)`` representing the owner of the current request.
        The index is computed as ``hash % num_buckets`` where ``hash`` is the request's key.
        """
